#!/usr/bin/env bash
# Publish an already-built Flatpak OSTree ref into the persistent signed Pages repo.
# Usage: FLATPAK_GPG_KEY_ID=... bash scripts/update-flatpak-pages.sh PAGES_DIR BUILT_REPO HTTPS_URL
# BUILT_REPO is the repo generated by flatpak-builder --repo, NOT a .flatpak bundle.
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
if (( $# != 3 )); then
  echo "Usage: FLATPAK_GPG_KEY_ID=FINGERPRINT $0 PAGES_DIR BUILT_REPO HTTPS_URL" >&2
  exit 2
fi
REPO_DIR="$(realpath -m -- "$1")"
BUILT_REPO="$(realpath -- "$2")"
URL="$3"
KEY="${FLATPAK_GPG_KEY_ID:?Set FLATPAK_GPG_KEY_ID to the signing key fingerprint}"
APP_ID=org.neural_smith.PrintCreator
ARCH="${RPC_FLATPAK_ARCH:-x86_64}"
BRANCH=master
APP_REF="app/${APP_ID}/${ARCH}/${BRANCH}"
for cmd in flatpak ostree gpg python3; do
  command -v "$cmd" >/dev/null || { echo "Missing required program: $cmd" >&2; exit 1; }
done
[[ -f "$BUILT_REPO/config" ]] || { echo "Missing built Flatpak OSTree repository: $BUILT_REPO" >&2; exit 1; }
[[ "$REPO_DIR" != "$BUILT_REPO" ]] || { echo 'Source and destination repositories must differ' >&2; exit 1; }
[[ "$URL" == https://* ]] || { echo 'Repository URL must be HTTPS' >&2; exit 1; }
gpg --batch --list-secret-keys "$KEY" >/dev/null
FINGERPRINT="$(gpg --batch --with-colons --fingerprint "$KEY" | awk -F: '$1 == "fpr" { print $10; exit }')"
[[ -n "$FINGERPRINT" ]] || { echo 'Could not identify signing key' >&2; exit 1; }

# Verify the source before touching the published repository.
SOURCE_COMMIT="$(ostree --repo="$BUILT_REPO" rev-parse "$APP_REF")"
[[ "$SOURCE_COMMIT" =~ ^[[:xdigit:]]{64}$ ]] || { echo "Invalid source commit for $APP_REF" >&2; exit 1; }
mkdir -p "$REPO_DIR"
if [[ -s "$REPO_DIR/flatpak-signing-fingerprint.txt" ]]; then
  [[ "$(cat "$REPO_DIR/flatpak-signing-fingerprint.txt")" == "$FINGERPRINT" ]] || {
    echo 'Signing key changed: refusing unsafe key rotation for existing Flatpak clients.' >&2
    exit 1
  }
fi
if [[ ! -f "$REPO_DIR/config" ]]; then
  ostree --repo="$REPO_DIR" init --mode=archive-z2
fi

# OSTree does not necessarily create empty refs/remotes on init; Git never
# preserves empty directories on gh-pages. Flatpak's AppStream/static-delta
# update can fail with opendir(refs/remotes) if this is missing.
mkdir -p "$REPO_DIR/refs/heads" "$REPO_DIR/refs/remotes"

# No flatpak build-import-bundle here. It has already failed with a null remote
# assertion on this CI setup. Transfer the app ref from the build-produced repo.
ostree --repo="$REPO_DIR" pull-local --untrusted "$BUILT_REPO" "$APP_REF"
PUBLISHED_COMMIT="$(ostree --repo="$REPO_DIR" rev-parse "$APP_REF")"
[[ "$PUBLISHED_COMMIT" == "$SOURCE_COMMIT" ]] || { echo 'Transferred Flatpak commit differs from built commit' >&2; exit 1; }

# The build-stage commit is unsigned. Sign the *published* commit and summary.
flatpak build-sign --gpg-sign="$FINGERPRINT" \
  --gpg-homedir="${GNUPGHOME:-$HOME/.gnupg}" \
  --arch="$ARCH" "$REPO_DIR" "$APP_ID" "$BRANCH"
flatpak build-update-repo --title='Print Creator' \
  --gpg-sign="$FINGERPRINT" --gpg-homedir="${GNUPGHOME:-$HOME/.gnupg}" \
  --generate-static-deltas --prune --prune-depth=2 "$REPO_DIR"

PUBLIC_KEY="$(mktemp)"
trap 'rm -f -- "$PUBLIC_KEY"' EXIT
gpg --batch --export "$FINGERPRINT" > "$PUBLIC_KEY"
[[ -s "$PUBLIC_KEY" ]] || { echo 'Failed to export public GPG key' >&2; exit 1; }
python3 "$ROOT/scripts/generate-flatpak-pages.py" --repo "$REPO_DIR" \
  --url "$URL" --gpg-public-key "$PUBLIC_KEY"
printf '%s\n' "$FINGERPRINT" > "$REPO_DIR/flatpak-signing-fingerprint.txt"
[[ -s "$REPO_DIR/summary" && -s "$REPO_DIR/summary.sig" ]] || {
  echo 'Missing signed OSTree summary; refusing to publish' >&2; exit 1
}
echo "Published signed $APP_REF: $PUBLISHED_COMMIT"
echo "Install URL: ${URL%/}/${APP_ID}.flatpakref"
